import type { StatId } from '../stats/types';
import type { AffixDef, AffixStatLine, AffixTier } from './types';

/**
 * ~40 affixes with 10 tiers each. Tiers are generated by interpolating from the
 * worst tier (item level 1) to the best (item level 90), slightly curved so the
 * top tiers feel special. Index 0 = worst; shown to players as T10…T1.
 */
export const TIER_ILVLS = [1, 10, 20, 30, 40, 50, 60, 70, 80, 90];
const TIER_WEIGHTS = [100, 100, 100, 90, 90, 80, 70, 60, 50, 40];

type Range = [number, number];
/** One line: worst-tier range and best-tier range. */
type LineSpec = AffixStatLine & { worst: Range; best: Range };

/** Content ids are snake_case; affix groups keep their camelCase names. */
const snake = (x: string) => x.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);

function roundFor(best: number, v: number): number {
  return best < 5 ? Math.round(v * 10) / 10 : Math.round(v);
}

function tiersFor(lines: LineSpec[]): AffixTier[] {
  return TIER_ILVLS.map((ilvl, t) => {
    const f = (t / 9) ** 1.15;
    return {
      ilvl,
      weight: TIER_WEIGHTS[t]!,
      ranges: lines.map((l) => {
        const lo = l.worst[0] + (l.best[0] - l.worst[0]) * f;
        const hi = l.worst[1] + (l.best[1] - l.worst[1]) * f;
        return [roundFor(l.best[0], lo), roundFor(l.best[1], hi)] as const;
      }),
    };
  });
}

function affix(
  id: string,
  kind: 'prefix' | 'suffix',
  allowedTags: string[],
  lines: LineSpec[],
  group = id,
): AffixDef {
  return {
    id: `affix.${snake(id)}`,
    kind,
    group,
    allowedTags,
    lines: lines.map(({ worst: _w, best: _b, ...line }) => line),
    tiers: tiersFor(lines),
  };
}

const line = (
  stat: StatId,
  kind: AffixStatLine['kind'],
  worst: Range,
  best: Range,
  opts: Partial<AffixStatLine> = {},
): LineSpec => ({
  stat,
  kind,
  worst,
  best,
  ...opts,
});

