const ANY_GEAR = ['weapon', 'armourPiece', 'shield', 'quiver', 'focus', 'belt', 'ring', 'amulet'];

function ashen(id: string, lines: (AffixStatLine & { range: Range })[]): AffixDef {
  return {
    id: `affix.ashen_${snake(id)}`,
    kind: 'ashen',
    group: `ashen_${id}`,
    allowedTags: ANY_GEAR,
    lines: lines.map(({ range: _r, ...l }) => l),
    tiers: [{ ilvl: 1, weight: 100, ranges: lines.map((l) => l.range) }],
  };
}

